import{_ as a,a as t,b as o,c as i,d as n,e as r,f as s,g as l}from"./chunks/Install22b.DDLege5l.js";import{_ as p}from"./chunks/Install17.CwCXrGHM.js";import{_ as d,o as h,c,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const I=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/install.md","filePath":"troubleshoot/install.md"}'),u={name:"troubleshoot/install.md"};function f(g,e,y,b,_,k){return h(),c("div",null,[...e[0]||(e[0]=[m('<h2 id="my-phone-says-this-app-is-very-dangerous" tabindex="-1">My phone says this app is very dangerous <a class="header-anchor" href="#my-phone-says-this-app-is-very-dangerous" aria-label="Permalink to &quot;My phone says this app is very dangerous&quot;">​</a></h2><p>GitHub releases from the <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">official repository</a> are safe. Ignore this message.</p><img src="'+a+'" style="zoom:75%;"><br><h2 id="i-cannot-find-the-file-i-downloaded" tabindex="-1">I cannot find the file I downloaded <a class="header-anchor" href="#i-cannot-find-the-file-i-downloaded" aria-label="Permalink to &quot;I cannot find the file I downloaded&quot;">​</a></h2><p>Open a file explorer and look into the Downloads folder of your phone&#39;s internal storage: you should see a file called something like <code>xDrip-plus-20yymmdd-cccccccc.apk</code></p><br><h2 id="when-i-touch-the-xdrip-apk-it-opens-a-file-list" tabindex="-1">When I touch the xDrip .apk it opens a file list <a class="header-anchor" href="#when-i-touch-the-xdrip-apk-it-opens-a-file-list" aria-label="Permalink to &quot;When I touch the xDrip .apk it opens a file list&quot;">​</a></h2><p>If the xDrip-plus file ends with .zip, rename it to .apk and retry.</p><p>If there&#39;s no way to open it with the installer package, try with an <a href="https://play.google.com/store/apps/details?id=com.apkinstaller.ApkInstaller" target="_blank" rel="noreferrer">APK installer</a>.</p><br><h2 id="i-cannot-install-unknown-apps" tabindex="-1">I cannot install unknown apps <a class="header-anchor" href="#i-cannot-install-unknown-apps" aria-label="Permalink to &quot;I cannot install unknown apps&quot;">​</a></h2><img src="'+t+'" style="zoom:75%;"><p>In Android settings -&gt; <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">Security settings</a> you need to allow the app you&#39;re using to open the downloaded file to install files from unknown sources; if available, select only this time.</p><p>Below is the example for Chrome; you might be using another app to open the xDrip .apk file.</p><img src="'+o+'" style="zoom:75%;"><br><h2 id="i-cannot-install-the-app" tabindex="-1">I cannot install the app <a class="header-anchor" href="#i-cannot-install-the-app" aria-label="Permalink to &quot;I cannot install the app&quot;">​</a></h2><img src="'+i+'" style="zoom:75%;"><p>Make sure you don&#39;t have a different version of xDrip installed: you can update or downgrade only apps from the same developer. If necessary <a href="./reinstall.html">reinstall</a> xDrip to switch from the official version to a forked version (and vice versa).</p><br><h2 id="my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" tabindex="-1"><strong>My phone says this app is unsafe and has been built for an older Android version</strong> <a class="header-anchor" href="#my-phone-says-this-app-is-unsafe-and-has-been-built-for-an-older-android-version" aria-label="Permalink to &quot;**My phone says this app is unsafe and has been built for an older Android version**&quot;">​</a></h2><p>Ignore it with More details, then Install anyway.</p><img src="'+n+'" style="zoom:75%;"><br><h2 id="xdrip-needs-background-location" tabindex="-1">xDrip needs background location <a class="header-anchor" href="#xdrip-needs-background-location" aria-label="Permalink to &quot;xDrip needs background location&quot;">​</a></h2><img src="'+r+'" style="zoom:60%;"><p>If you want xDrip to connect to a Bluetooth device, it needs to have permanent <a href="./../install/install.html#enable-location">access to location</a>.</p><p>For newer Android versions go to Android Settings -&gt; Location -&gt; Apps -&gt; xDrip or Android Settings -&gt; Apps -&gt; xDrip -&gt; Location and check that Allow all the time is enabled.</p><img src="'+p+'" style="zoom:80%;"><br><h2 id="xdrip-needs-battery-optimization-whitelisting" tabindex="-1">xDrip needs battery optimization whitelisting <a class="header-anchor" href="#xdrip-needs-battery-optimization-whitelisting" aria-label="Permalink to &quot;xDrip needs battery optimization whitelisting&quot;">​</a></h2><img src="'+s+'" style="zoom:60%;"><p>xDrip should not be optimized at all.</p><p>This setting location will vary from brand to brand and Android version; you will usually find it in Android Settings -&gt; Apps -&gt; xDrip -&gt; Battery</p><img src="'+l+'" style="zoom:100%;"><p>You might need to reboot your phone to apply these changes. If the warning message remains, make sure you are using a recent xDrip version: update it if necessary.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.03.27" target="_blank" rel="noreferrer"><em>Last modified 28/3/2022</em></a></p>',39)])])}const D=d(u,[["render",f]]);export{I as __pageData,D as default};
